    "@superfunctions/botfn-shared-types": "workspace:*"
  }
}
```

3. Create `src/core.ts` with business logic:
```typescript
import { Hono } from 'hono';
import { z } from 'zod';
// Import platform-specific utilities as needed
// import { verifyDiscordRequest } from '@superfunctions/botfn-discord-core';
// import { verifySlackRequest } from '@superfunctions/botfn-slack-core';

// Define schemas
const CommandOptionsSchema = z.object({
  // your command options
});

// Define handlers
export function createBotHandlers(env: any) {
  return {
    async handleCommand(interaction: any) {
      // Business logic here
    }
  };
}

// Export core app factory
export function createBotApp() {
  const app = new Hono();

  app.post('/interactions', async (c) => {
    const env = c.env;
    const handlers = createBotHandlers(env);

    // Handle bot interactions
    // ...

    return c.json({ type: 1 }); // Response format depends on platform
  });

  return app;
}
```

4. Create platform-specific entry points:

**`src/index.cloudflare.ts`**:
```typescript
import { createBotApp } from './core';

const app = createBotApp();

export default app;
```

**`src/index.digitalocean.ts`**:
```typescript
import { createBotApp } from './core';

const app = createBotApp();

// DigitalOcean Functions use Node.js runtime
// Export the handler for the serverless function
export const main = app.fetch;
```

**`src/index.vercel.ts`**:
```typescript
import { handle } from '@hono/vercel';
import { createBotApp } from './core';

const app = createBotApp();

export default handle(app);
```

## validation with Zod

Always validate bot interaction data and external inputs:

```typescript
import { z } from 'zod';

const LinkCommandSchema = z.object({
  repository: z.string().min(1),
  search: z.string().min(1),
});

// In handler
const options = interaction.data.options;
const parsed = LinkCommandSchema.safeParse({
  repository: options.find(opt => opt.name === 'repository')?.value,
  search: options.find(opt => opt.name === 'search')?.value,
});

if (!parsed.success) {
  return { content: '❌ Invalid command options' };
}

const { repository, search } = parsed.data;
```

## environment variables

Each platform has different patterns for accessing environment variables:

- **Cloudflare**: `c.env.VARIABLE_NAME`
- **DigitalOcean**: `process.env.VARIABLE_NAME`
- **Vercel**: `process.env.VARIABLE_NAME`

Handle this in platform-specific files or create an env adapter in core.ts.

## deployment

### Cloudflare Workers
```bash
cd bots/my-bot
npm run deploy:cloudflare
```

Requires `wrangler.toml`:
```toml
name = "my-bot"
main = "src/index.cloudflare.ts"
compatibility_date = "2024-01-01"

[vars]
# Non-secret variables
```

### Digital Ocean Functions
```bash
cd bots/my-bot
doctl serverless deploy
```

Requires `.do/app.yaml`:
```yaml
functions:
  - name: my-bot
    runtime: nodejs:18
    source_dir: src
    entry_point: index.digitalocean.ts
```

### Vercel
```bash
cd bots/my-bot
npm run deploy:vercel
```

Requires `vercel.json`:
```json
{
  "functions": {
    "src/index.vercel.ts": {
      "runtime": "@vercel/node@3"
    }
  }
}
```

## development workflow

1. Make changes in `core.ts` or shared packages
2. Test locally: `npm run dev` (runs Cloudflare dev by default)
3. Build all bots: `npm run build` (from repo root)
4. Deploy to target platform: `npm run deploy:[platform]`

## best practices

1. **Keep core.ts platform-agnostic** - No platform-specific APIs
2. **Validate all inputs** - Use Zod schemas for type safety
3. **Use workspace dependencies** - Reference shared packages with `workspace:*`
4. **Handle errors gracefully** - Always return user-friendly error messages
5. **Test with multiple platforms** - Ensure compatibility across all targets
6. **Document environment variables** - List all required env vars in bot README
=== PR AGENTS
# BotFn architecture

BotFn lives inside Superfunctions as nested workspaces at `botfn/<pkg>`. There is no BotFn-root `package.json` or Turborepo of its own. Do not recreate a `bots/` + `packages/` layout, DigitalOcean/Vercel entrypoints, or badges/CI for a standalone BotFn GitHub repo.

## Technology stack

- **Framework**: [Hono](https://hono.dev/)
- **Validation**: [Zod](https://zod.dev/)
- **Runtime**: Cloudflare Workers (`wrangler`)
- **Persistence**: Postgres via `DATABASE_URL` (Drizzle), not D1

## Layout

```
botfn/
├── bot-discord/          # @botfn/discord-bot — src/core.ts + src/index.cloudflare.ts
├── bot-slack/            # @botfn/bot-slack — Cloudflare Worker
├── discord-core/         # @botfn/discord-core
├── slack-core/           # @botfn/slack-core
├── github-integration/   # @botfn/github-integration
├── linear-integration/   # @botfn/linear-integration
├── shared-types/         # @botfn/shared-types
├── persistence/          # @botfn/persistence-service — Cloudflare Worker + Postgres
└── admin/                # @botfn/admin
```

Bots keep platform-agnostic handlers in `src/core.ts` (or `src/index.ts` for Slack) and a Cloudflare entrypoint (`src/index.cloudflare.ts` or Wrangler `main`). Deploy with `wrangler`; do not add `index.digitalocean.ts` / `index.vercel.ts`.

## Shared packages

- **discord-core**: Ed25519 signature verification, interaction constants, response helpers
- **slack-core**: Slack signing-secret verification (Web Crypto HMAC)
- **github-integration**: GitHub App JWT and API wrapper
- **linear-integration**: Linear GraphQL helpers
- **shared-types**: Zod schemas for command options and env shapes
- **persistence**: tRPC + Hono Worker; Postgres through `DATABASE_URL`

Workspace dependencies use `*` / `workspace` names (`@botfn/...`) from the Superfunctions root.

## Cloudflare deployment

Each deployable package has a `wrangler.toml` and `npm run deploy` / `deploy:cloudflare`. Secrets go in Wrangler (`wrangler secret put ...`), including persistence `DATABASE_URL`. Discord and Slack env access is `c.env.VARIABLE_NAME`.

## Development workflow

1. Change `core.ts` or a shared `botfn/<pkg>` package.
2. Run the Worker locally: `npm run dev --workspace @botfn/discord-bot` (or `@botfn/bot-slack`).
3. Test/build from the Superfunctions root with turbo filters on `./botfn/*`.
4. Deploy the target Worker only.

